#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

std::string largestNumber(const std::vector<int>& nums) {
    std::vector<std::string> parts;
    for (int x : nums) {
        parts.push_back(std::to_string(x));
    }
    std::sort(parts.begin(), parts.end(), [](const std::string& a, const std::string& b) {
        return a + b > b + a;
    });
    if (parts[0] == "0") {
        return "0";
    }
    std::string result;
    for (const std::string& part : parts) {
        result += part;
    }
    return result;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    std::cout << largestNumber(nums) << "\n";
    return 0;
}

